{
  "topics": [
    {
      "id": "qrv.t01",
      "statements": {
        "f1": "The Pass scheduling API primary host is qrv-nemora.qrv.invalid. Mission-operations consoles use it to read confirmed contact windows.",
        "f2": "On 2026-03-12, the Pass scheduling API primary host changed to qrv-iskara.qrv.invalid after the previous host developed intermittent connection resets.",
        "d": "The Pass scheduling API publishes confirmed windows only after antenna availability and mission priority checks complete."
      },
      "query": "What is the current primary host for the Pass scheduling API?"
    },
    {
      "id": "qrv.t02",
      "statements": {
        "f1": "The TLE ingest gateway landing bucket is qrv-tle-mavrin. Incoming element files land there before parsing and source validation.",
        "f2": "On 2026-02-18, the TLE ingest gateway landing bucket changed to qrv-track-selin because the previous bucket's event notifications were unreliable.",
        "d": "The TLE ingest gateway records source metadata before promoting accepted element files to the tracking pipeline."
      },
      "query": "Which landing bucket does the TLE ingest gateway currently use?"
    },
    {
      "id": "qrv.t03",
      "statements": {
        "f1": "The Telemetry decoder farm uses qrv-dq-kelmar as its dispatch queue. Workers claim packet batches from it by spacecraft family.",
        "f2": "On 2026-04-09, the Telemetry decoder farm dispatch queue changed to qrv-dq-mirven to isolate decoder traffic from a congested broker partition.",
        "d": "Decoder workers preserve the raw packet reference alongside each decoded frame so operators can investigate malformed payloads."
      },
      "query": "What is the Telemetry decoder farm's current dispatch queue?"
    },
    {
      "id": "qrv.t04",
      "statements": {
        "f1": "The Azimuth drive controller position polling interval is 1180 ms. The console uses those samples to display antenna motion during a pass.",
        "f2": "On 2026-05-14, the Azimuth drive controller position polling interval changed to 920 ms to make tracking deviations visible sooner.",
        "d": "The Azimuth drive controller marks position samples invalid when the encoder reports a fault, rather than displaying the last good bearing."
      },
      "query": "What is the Azimuth drive controller's current position polling interval?"
    },
    {
      "id": "qrv.t05",
      "statements": {
        "f1": "The Mission operations console deployed release is qrv-moc-5.7.3. Operators use its pass timeline and decoder health panels during staffed contacts.",
        "f2": "On 2026-06-03, the Mission operations console deployed release changed to qrv-moc-4.6.2 after a compatibility issue with the station display adapters.",
        "d": "The Mission operations console shows an acknowledgement banner when an operator takes control of an active contact."
      },
      "query": "Which release is currently deployed for the Mission operations console?"
    },
    {
      "id": "qrv.t06",
      "statements": {
        "f1": "The Beacon packet archive retention period is 63 days. Archived packets remain searchable by spacecraft and ground-station pass.",
        "f2": "On 2026-01-27, the Beacon packet archive retention period changed to 42 days to reduce duplicate storage after the analytics copy was verified.",
        "d": "The Beacon packet archive indexes receive timestamps separately from spacecraft timestamps so delayed packets remain discoverable."
      },
      "query": "What is the current packet retention period for the Beacon packet archive?"
    },
    {
      "id": "qrv.t07",
      "statements": {
        "f1": "The Ranging reconciliation job starts daily at 02:39 UTC. It compares station measurements with the prior day's contact records.",
        "f2": "On 2026-03-25, the Ranging reconciliation job daily start time changed to 03:46 UTC to avoid overlap with the measurement import.",
        "d": "The Ranging reconciliation job flags unmatched observations for review instead of silently dropping them from its report."
      },
      "query": "At what time does the Ranging reconciliation job currently start each day?"
    },
    {
      "id": "qrv.t08",
      "statements": {
        "f1": "The Contact plan exporter uses qrv-windowloom as its rendering tool. It produces the station-facing plan from approved contact windows.",
        "f2": "On 2026-07-08, the Contact plan exporter rendering tool changed to qrv-slotcaster to fix pagination of overlapping contacts.",
        "d": "The Contact plan exporter attaches a generation timestamp and plan revision to every station-facing document."
      },
      "query": "Which rendering tool does the Contact plan exporter currently use?"
    },
    {
      "id": "qrv.t09",
      "statements": {
        "f1": "The Element freshness monitor stale-element alert threshold is 70 min. It checks the latest accepted element set for each tracked spacecraft.",
        "f2": "On 2026-02-05, the Element freshness monitor stale-element alert threshold changed to 40 min after delayed ingest obscured a tracking risk.",
        "d": "The Element freshness monitor checks the latest accepted element set for each tracked spacecraft and routes alerts to the tracking desk."
      },
      "query": "What is the Element freshness monitor's current stale-element alert threshold?"
    },
    {
      "id": "qrv.t10",
      "statements": {
        "f1": "The Ground station outage notifier sends alerts to qrv-ops-pulsar as its notification channel. Messages include station ID and incident status.",
        "f2": "On 2026-04-21, the Ground station outage notifier notification channel changed to qrv-station-ember to separate station incidents from routine operations traffic.",
        "d": "The Ground station outage notifier deduplicates repeated loss-of-connectivity events while an incident remains open."
      },
      "query": "What is the current notification channel for the Ground station outage notifier?"
    },
    {
      "id": "qrv.t11",
      "statements": {
        "f1": "The Uplink command audit view dashboard is named qrv-panel-estuary. It groups command acknowledgements by spacecraft and operator session.",
        "d": "The Uplink command audit view links each issued command to its approval record and downlink acknowledgement when available."
      },
      "query": "What is the dashboard name for the Uplink command audit view?"
    },
    {
      "id": "qrv.t12",
      "statements": {
        "f1": "RF chain calibration uses qrv-cal-lumet as its calibration service. Technicians attach sweep results to the relevant station work order.",
        "d": "RF chain calibration records ambient temperature with each sweep so later comparisons account for equipment conditions."
      },
      "query": "Which calibration service does RF chain calibration use?"
    },
    {
      "id": "qrv.t13",
      "statements": {
        "f1": "Command signing key rotation runs on a cadence of 49 days. The custodian records each completed rotation in the access ledger.",
        "d": "Command signing key rotation requires a second custodian to verify the new public-key fingerprint before activation."
      },
      "query": "What is the cadence for Command signing key rotation?"
    },
    {
      "id": "qrv.t14",
      "statements": {
        "f1": "The S band downlink modem active demodulation profile is qrv-sb-alten. It is used for routine beacon capture at staffed stations.",
        "f2": "On 2026-05-06, the S band downlink modem active demodulation profile changed to qrv-sb-brevix for a trial of improved weak-signal acquisition.",
        "f3": "On 2026-05-19, the S band downlink modem active demodulation profile reverted to qrv-sb-alten after the trial produced unstable frame lock."
      },
      "query": "Which demodulation profile is currently active on the S band downlink modem?"
    },
    {
      "id": "qrv.t15",
      "statements": {
        "f1": "The Cross station handover contact guard interval is 14 seconds. The scheduler leaves that gap between adjacent station assignments.",
        "f2": "On 2026-06-11, the Cross station handover contact guard interval changed to 17 seconds to allow more time for antenna release.",
        "f3": "On 2026-06-23, the Cross station handover contact guard interval returned to 14 seconds after controller timing measurements showed the extra margin was unnecessary."
      },
      "query": "What is the current contact guard interval for Cross station handover?"
    },
    {
      "id": "qrv.t16",
      "statements": {
        "f1": "The Emergency uplink relay failover host is qrv-jexora.qrv.invalid. Operators use the relay only when the normal uplink path is unavailable.",
        "f2": "On 2026-07-02, the Emergency uplink relay failover host changed to qrv-zunara.qrv.invalid during maintenance on the previous host.",
        "f3": "On 2026-07-10, the Emergency uplink relay failover host returned to qrv-jexora.qrv.invalid after maintenance and link checks were completed."
      },
      "query": "What is the current failover host for the Emergency uplink relay?"
    }
  ],
